/* NIK/phone checks use the shared server dataset across both branches. */
let identityCustomerSaving=false;
function identityInput(form){return {phone:form.querySelector('[name="phone"]')?.value.trim()||'',nik:form.querySelector('[name="nik"]')?.value.trim()||'',...(form.dataset.identityExclude?{exclude:form.dataset.identityExclude}:{})}}
function identitySignature(input){return JSON.stringify(input)}
function identityMatchesHtml(result){return result.matches.length?'<strong>Duplikat ditemukan ('+result.matches.length+')</strong>'+result.matches.map(m=>'<article class="identity-match"><strong>'+E(m.name||'Data di luar akses Anda')+'</strong><span>'+E(m.relation)+' · '+E(m.branch)+'</span><small>Cocok: '+E((m.matchedOn||['NIK / Telepon']).join(' & '))+'</small>'+(m.accessible&&(m.relation==='Customer'||m.lead)?btn('Buka data existing',"document.querySelector('#modal').close();"+leadCall('go',m.relation==='Customer'?'Nasabah detail':'Lead detail',m.relation==='Customer'?m.profile:m.lead)):'<small>Koordinasikan dengan SPV/cabang penanggung jawab.</small>')+'</article>').join(''):'<strong>Tidak ditemukan duplikat</strong><span>NIK/telepon yang diisi belum cocok dengan data CRM saat ini. Penyimpanan akan diperiksa kembali oleh server.</span>'}
async function identityRun(form=document.querySelector('#form')){const panel=form?.querySelector('.identity-check');if(!panel)return null;const snapshot=identityInput(form),signature=identitySignature(snapshot),seq=String(Number(panel.dataset.seq||0)+1);panel.dataset.seq=seq;panel.dataset.status='loading';const result=panel.querySelector('[role="status"]'),button=panel.querySelector('button');button.disabled=true;result.textContent='Memeriksa NIK dan telepon di seluruh cabang…';try{const check=await api('identity-duplicates',snapshot);if(!form.isConnected||panel.dataset.seq!==seq||identitySignature(identityInput(form))!==signature)return null;result.innerHTML=identityMatchesHtml(check);panel.dataset.status=check.matches.length?'duplicate':'clear';return check;}catch(e){if(form.isConnected&&panel.dataset.seq===seq){result.textContent=e.message;panel.dataset.status='error';}throw e;}finally{if(panel.dataset.seq===seq)button.disabled=false;}}
function identityCheckAttach({exclude='',guard=false}={}){const form=document.querySelector('#form');if(!form||form.querySelector('.identity-check')||!form.querySelector('[name="phone"]'))return;form.dataset.identityExclude=exclude;form.querySelector('#leadDuplicateResult')?.remove();form.querySelector('button[onclick="leadDuplicateCheck()"]')?.remove();const panel=document.createElement('section');panel.className='identity-check';panel.dataset.status='idle';panel.innerHTML='<div><strong>Cek Duplikat NIK & Telepon</strong><button type="button">Cek duplikat</button></div><p>Memeriksa Leads dan Customer lintas cabang di CRM. Akses detail mengikuti hak pengguna.</p><div role="status" aria-live="polite">Isi NIK atau telepon lengkap untuk memeriksa.</div>';const anchor=form.querySelector('[name="nik"]')||form.querySelector('[name="phone"]');anchor.closest('label').after(panel);panel.querySelector('button').onclick=()=>identityRun(form).catch(()=>{});let timer;const changed=()=>{clearTimeout(timer);panel.dataset.seq=String(Number(panel.dataset.seq||0)+1);panel.querySelector('button').disabled=false;panel.dataset.status='idle';panel.querySelector('[role="status"]').textContent='Identitas berubah. Hasil sebelumnya tidak berlaku.';const input=identityInput(form);if(input.phone.replace(/\D/g,'').length>=8||/^\d{16}$/.test(input.nik))timer=setTimeout(()=>identityRun(form).catch(()=>{}),600);};for(const input of form.querySelectorAll('[name="phone"],[name="nik"]')){input.addEventListener('input',changed);input.addEventListener('blur',()=>{clearTimeout(timer);const value=identityInput(form);if(value.phone||value.nik)identityRun(form).catch(()=>{})})}form.addEventListener('reset',()=>clearTimeout(timer));document.querySelector('#modal').addEventListener('close',()=>clearTimeout(timer),{once:true});
 if(guard){const before=form.onsubmit;let busy=false;form.onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;const signature=identitySignature(identityInput(form)),button=form.querySelector('button.primary');button.disabled=true;try{const r=await identityRun(form);if(!r||signature!==identitySignature(identityInput(form)))throw Error('Identitas berubah. Periksa kembali sebelum menyimpan.');if(r.matches.length)throw Error('NIK/telepon sudah tercatat. Gunakan data existing atau koordinasikan dengan SPV.');before.call(form,event);}catch(e){form.querySelector('#formerror').textContent=e.message;}finally{busy=false;button.disabled=false;}};}}
const identityCreateLeadBefore=createLead;
createLead=function(){identityCreateLeadBefore();if(!journey)identityCheckAttach()};
const identityEditLeadBefore=leadIdentityEdit;
leadIdentityEdit=function(id){identityEditLeadBefore(id);const lead=db.leads.find(l=>l.id===id);if(lead&&document.querySelector('#form [name="phone"]'))identityCheckAttach({exclude:lead.profile,guard:true})};
const identityDirectCustomerBefore=directCustomer;
directCustomer=function(){if(journey)return identityDirectCustomerBefore();modal('Buat Customer',field('Nama orang / perusahaan','name','','text',true)+field('CIF','cif')+field('NIK (opsional, 16 digit)','nik')+field('Nama kontak','contact')+field('Nomor telepon','phone','','tel',true)+field('Alamat','address')+field('Alamat usaha / tempat bekerja','businessAddress')+field('Pekerjaan / bidang usaha','occupation')+ownerSelect(),f=>{if(identityCustomerSaving)return false;if(f.nik&&!/^\d{16}$/.test(f.nik))throw Error('NIK harus 16 digit.');identityCustomerSaving=true;const form=document.querySelector('#form'),submit=form.querySelector('button.primary'),snapshot=identitySignature(identityInput(form));submit.disabled=true;(async()=>{if(saving)throw Error('Tunggu penyimpanan sebelumnya selesai.');const result=await identityRun(form);if(!result||snapshot!==identitySignature(identityInput(form)))throw Error('Identitas berubah. Periksa kembali sebelum menyimpan.');if(result.matches.length)throw Error('NIK/telepon sudah tercatat. Buka data existing atau koordinasikan dengan SPV.');const p={...f,id:uid('P'),relation:'Customer',customerSource:'Input Langsung',dataSource:'Pencatatan CRM',created:now(),ownerId:memberList.find(m=>m.name===f.owner)?.id};const r=await api('sync',{changes:[{collection:'profiles',id:p.id,before:null,next:p}],action:'Buat Customer langsung',object:p.id,detail:p.name});document.querySelector('#modal').close();applyServer(r);go('Nasabah detail',p.id);toast('Customer tersimpan');})().catch(e=>{if(form.isConnected)form.querySelector('#formerror').textContent=e.message;else toast(e.message)}).finally(()=>{identityCustomerSaving=false;submit.disabled=false});return false;});identityCheckAttach()};
